SELECT '=== UAT RESET VERIFICATION ===' as section;

-- ============================================================================
-- 1. USER COUNTS
-- ============================================================================

SELECT '=== USER COUNTS ===' as section;

SELECT
  'SUPER_ADMIN count' as check_item,
  COUNT(*) as actual,
  1 as expected,
  CASE WHEN COUNT(*) = 1 THEN '✅ PASS' ELSE '❌ FAIL' END as status
FROM profiles
WHERE role = 'SUPER_ADMIN'
UNION ALL
SELECT
  'ADMIN count',
  COUNT(*),
  0 as expected,
  CASE WHEN COUNT(*) = 0 THEN '✅ PASS' ELSE '❌ FAIL' END
FROM profiles
WHERE role = 'ADMIN'
UNION ALL
SELECT
  'TECHNICIAN profiles count',
  COUNT(*),
  0,
  CASE WHEN COUNT(*) = 0 THEN '✅ PASS' ELSE '❌ FAIL' END
FROM profiles
WHERE role = 'TECHNICIAN'
UNION ALL
SELECT
  'auth.users count',
  COUNT(*),
  1,
  CASE WHEN COUNT(*) = 1 THEN '✅ PASS' ELSE '❌ FAIL' END
FROM auth.users;

