-- 5. CONFIGURATION PRESERVED
-- ============================================================================

SELECT '=== CONFIGURATION CHECK ===' as section;

SELECT
  'user_role enum' as config_item,
  CASE WHEN EXISTS (
    SELECT 1 FROM pg_type WHERE typname = 'user_role'
  ) THEN '✅ EXISTS' ELSE '❌ MISSING' END as status
UNION ALL
SELECT
  'ticket_status enum',
  CASE WHEN EXISTS (
    SELECT 1 FROM pg_type WHERE typname = 'ticket_status'
  ) THEN '✅ EXISTS' ELSE '❌ MISSING' END
UNION ALL
SELECT
  'ticket_activity_type enum',
  CASE WHEN EXISTS (
    SELECT 1 FROM pg_type WHERE typname = 'ticket_activity_type'
  ) THEN '✅ EXISTS' ELSE '❌ MISSING' END
UNION ALL
SELECT
  'Storage bucket: ticket-evidences',
  CASE WHEN EXISTS (
    SELECT 1 FROM storage.buckets WHERE id = 'ticket-evidences'
  ) THEN '✅ EXISTS' ELSE '❌ MISSING' END
UNION ALL
SELECT
  'Storage bucket: ticket-signatures',
  CASE WHEN EXISTS (
    SELECT 1 FROM storage.buckets WHERE id = 'ticket-signatures'
  ) THEN '✅ EXISTS' ELSE '❌ MISSING' END
UNION ALL
SELECT
  'auth.users record for SUPER_ADMIN',
  CASE WHEN EXISTS (
    SELECT 1 FROM auth.users au
    JOIN profiles p ON p.id = au.id
    WHERE p.role = 'SUPER_ADMIN'
  ) THEN '✅ EXISTS' ELSE '❌ MISSING' END;

