-- ============================================================================
-- FINAL SUMMARY
-- ============================================================================

SELECT '=== VERIFICATION SUMMARY ===' as section;

SELECT
  CASE
    WHEN (SELECT COUNT(*) FROM profiles) = 1
      AND (SELECT COUNT(*) FROM profiles WHERE role = 'SUPER_ADMIN') = 1
      AND (SELECT COUNT(*) FROM auth.users) = 1
      AND (SELECT COUNT(*) FROM tickets) = 0
      AND (SELECT COUNT(*) FROM ticket_activity) = 0
      AND (SELECT COUNT(*) FROM ticket_status_history) = 0
      AND (SELECT COUNT(*) FROM ticket_evidences) = 0
      AND (SELECT COUNT(*) FROM ticket_signatures) = 0
      AND (SELECT COUNT(*) FROM technicians) = 0
      AND (SELECT COUNT(*) FROM clients) = 0
      AND (SELECT COUNT(*) FROM technician_push_tokens) = 0
      AND (SELECT COUNT(*) FROM technician_locations) = 0
      AND (SELECT COUNT(*) FROM storage.objects WHERE bucket_id IN ('ticket-evidences', 'ticket-signatures')) = 0
    THEN '✅ ALL DB CHECKS PASSED'
    ELSE '❌ SOME CHECKS FAILED - REVIEW REQUIRED'
  END as overall_status;

